<?php
declare(strict_types=1);
namespace App\Controllers\Api;

class ExpenseBillsController extends ExpenseApiController
{
    public function index(){return$this->safe(function(){if(!$u=$this->user())return$this->missing();$b=db_connect()->table('expense_bills b')->select('b.*,s.status_code,s.status_name,ps.payment_status_code,p.project_name')->join('expense_bills_status_masters s','s.id=b.status_id')->join('expense_bills_payment_status_masters ps','ps.id=b.payment_status_id')->join('projects p','p.id=b.project_id')->where('b.company_id',$this->company($u))->where('b.deleted_at',null);foreach(['project_id','site_id','zone_id','request_id','status_id','payment_status_id']as$f)if($this->request->getGet($f)!==null)$b->where('b.'.$f,(int)$this->request->getGet($f));return$this->ok('Expense bills retrieved.','expense_bills',$b->orderBy('b.id','DESC')->get()->getResultArray());});}
    public function show(int$id){return$this->safe(function()use($id){if(!$u=$this->user())return$this->missing();$c=$this->company($u);if(!$r=$this->row('expense_bills',$id,$c))return$this->missing('Expense bill not found.');$db=db_connect();$r['items']=$db->table('expense_bill_items i')->select('i.*,ec.category_code,ec.category_name')->join('expense_categories ec','ec.id=i.expense_category_id')->where(['i.bill_id'=>$id,'i.company_id'=>$c])->where('i.deleted_at',null)->get()->getResultArray();$r['documents']=$db->table('expense_documents')->where(['bill_id'=>$id,'company_id'=>$c])->where('deleted_at',null)->get()->getResultArray();$r['allocations']=$db->table('expense_allocations')->where(['bill_id'=>$id,'company_id'=>$c])->where('deleted_at',null)->get()->getResultArray();$r['payments']=$db->table('expense_payments')->where(['bill_id'=>$id,'company_id'=>$c])->where('deleted_at',null)->get()->getResultArray();return$this->ok('Expense bill retrieved.','expense_bill',$r);});}
    public function create(){return$this->save();}public function update(int$id){return$this->save($id);}
    private function save(?int$id=null){return$this->safe(function()use($id){if(!$u=$this->user())return$this->missing();$d=$this->input();$e=$this->required($d,['project_id','bill_no','internal_voucher_no','bill_date','payee_type_id','payee_name']);if($e)return$this->invalid($e);$c=$this->company($u);$project=(int)$d['project_id'];if(!$this->project($project,$u,true))return$this->invalid(['project_id'=>'Project is invalid or inaccessible.']);$site=isset($d['site_id'])?(int)$d['site_id']:null;$zone=isset($d['zone_id'])?(int)$d['zone_id']:null;if(!$this->validSite($site,$project,$c)||!$this->validZone($zone,$site,$c))return$this->invalid(['site_id'=>'Site or zone does not belong to the project.']);$db=db_connect();$existing=$id?$this->row('expense_bills',$id,$c):null;if($id&&!$existing)return$this->missing('Expense bill not found.');if($existing&&$this->statusCode('expense_bills_status_masters','status_code',(int)$existing['status_id'])!=='DRAFT')return$this->conflict('Only draft bills can be updated.');$dup=$db->table('expense_bills')->where(['company_id'=>$c,'internal_voucher_no'=>trim($d['internal_voucher_no'])])->where('deleted_at',null);if($id)$dup->where('id !=',$id);if($dup->countAllResults())return$this->conflict('Internal voucher number already exists.');$row=['company_id'=>$c,'project_id'=>$project,'site_id'=>$site,'zone_id'=>$zone,'request_id'=>isset($d['request_id'])?(int)$d['request_id']:null,'supplier_id'=>isset($d['supplier_id'])?(int)$d['supplier_id']:null,'purchase_order_id'=>isset($d['purchase_order_id'])?(int)$d['purchase_order_id']:null,'material_receipt_id'=>isset($d['material_receipt_id'])?(int)$d['material_receipt_id']:null,'bill_no'=>trim($d['bill_no']),'internal_voucher_no'=>trim($d['internal_voucher_no']),'bill_date'=>$d['bill_date'],'due_date'=>$d['due_date']??null,'payee_type_id'=>(int)$d['payee_type_id'],'payee_name'=>trim($d['payee_name']),'payee_gstin'=>$d['payee_gstin']??null,'discount_amount'=>(float)($d['discount_amount']??0),'cgst_amount'=>(float)($d['cgst_amount']??0),'sgst_amount'=>(float)($d['sgst_amount']??0),'igst_amount'=>(float)($d['igst_amount']??0),'other_charges'=>(float)($d['other_charges']??0),'round_off'=>(float)($d['round_off']??0),'tds_amount'=>(float)($d['tds_amount']??0),'remarks'=>$d['remarks']??null,'updated_by'=>(int)$u->id];if($id)$db->table('expense_bills')->where('id',$id)->update($row);else{$row+=['subtotal'=>0,'taxable_amount'=>0,'gross_amount'=>0,'net_payable'=>0,'paid_amount'=>0,'outstanding_amount'=>0,'payment_status_id'=>$this->masterId('expense_bills_payment_status_masters','payment_status_code','UNPAID'),'status_id'=>$this->masterId('expense_bills_status_masters','status_code','DRAFT'),'created_by'=>(int)$u->id];$db->table('expense_bills')->insert($row);$id=(int)$db->insertID();}$this->recalculate($id);return$this->ok('Expense bill saved.','expense_bill',$this->row('expense_bills',$id,$c),$existing?200:201);});}
    public function addItem(int$id){return$this->safe(function()use($id){if(!$u=$this->user())return$this->missing();$c=$this->company($u);if(!$bill=$this->row('expense_bills',$id,$c))return$this->missing('Expense bill not found.');if($this->statusCode('expense_bills_status_masters','status_code',(int)$bill['status_id'])!=='DRAFT')return$this->conflict('Items can be added only to a draft bill.');$d=$this->input();$e=$this->required($d,['expense_category_id','description','quantity','rate','tax_rate']);if($e)return$this->invalid($e);$taxable=round((float)$d['quantity']*(float)$d['rate'],2);$tax=round($taxable*(float)$d['tax_rate']/100,2);$row=['company_id'=>$c,'project_id'=>$bill['project_id'],'bill_id'=>$id,'request_item_id'=>isset($d['request_item_id'])?(int)$d['request_item_id']:null,'expense_category_id'=>(int)$d['expense_category_id'],'description'=>trim($d['description']),'quantity'=>(float)$d['quantity'],'rate'=>(float)$d['rate'],'taxable_amount'=>$taxable,'tax_rate'=>(float)$d['tax_rate'],'tax_amount'=>$tax,'line_total'=>$taxable+$tax,'created_by'=>(int)$u->id,'updated_by'=>(int)$u->id];$db=db_connect();$db->table('expense_bill_items')->insert($row);$item=(int)$db->insertID();$this->recalculate($id);return$this->ok('Expense bill item added.','expense_bill_item',$this->row('expense_bill_items',$item,$c),201);});}
    public function addDocument(int$id){return$this->safe(function()use($id){if(!$u=$this->user())return$this->missing();$c=$this->company($u);if(!$this->row('expense_bills',$id,$c))return$this->missing('Expense bill not found.');$d=$this->input();$e=$this->required($d,['document_name','file_name','file_path']);if($e)return$this->invalid($e);$row=['company_id'=>$c,'bill_id'=>$id,'document_type_id'=>isset($d['document_type_id'])?(int)$d['document_type_id']:null,'document_name'=>trim($d['document_name']),'file_name'=>trim($d['file_name']),'file_path'=>trim($d['file_path']),'mime_type'=>$d['mime_type']??null,'file_size_bytes'=>isset($d['file_size_bytes'])?(int)$d['file_size_bytes']:null,'document_date'=>$d['document_date']??null,'is_primary'=>(int)($d['is_primary']??0),'uploaded_by'=>(int)$u->id];$db=db_connect();$db->table('expense_documents')->insert($row);return$this->ok('Expense document added.','expense_document',$this->row('expense_documents',(int)$db->insertID(),$c),201);});}
    public function allocate(int$id,int$itemId){return$this->safe(function()use($id,$itemId){if(!$u=$this->user())return$this->missing();$c=$this->company($u);$bill=$this->row('expense_bills',$id,$c);$item=$this->row('expense_bill_items',$itemId,$c);if(!$bill||!$item||(int)$item['bill_id']!==$id)return$this->missing('Expense bill item not found.');$d=$this->input();$e=$this->required($d,['budget_id','budget_line_id','allocated_amount','allocation_type_id']);if($e)return$this->invalid($e);$allocated=(float)(db_connect()->table('expense_allocations')->selectSum('allocated_amount','total')->where(['bill_item_id'=>$itemId,'company_id'=>$c])->where('deleted_at',null)->get()->getRowArray()['total']??0);if($allocated+(float)$d['allocated_amount']>(float)$item['line_total']+0.01)return$this->invalid(['allocated_amount'=>'Allocation exceeds bill item total.']);$row=['company_id'=>$c,'project_id'=>$bill['project_id'],'bill_id'=>$id,'bill_item_id'=>$itemId,'budget_id'=>(int)$d['budget_id'],'budget_line_id'=>(int)$d['budget_line_id'],'allocated_amount'=>(float)$d['allocated_amount'],'allocation_type_id'=>(int)$d['allocation_type_id'],'remarks'=>$d['remarks']??null,'created_by'=>(int)$u->id];$db=db_connect();$db->table('expense_allocations')->insert($row);return$this->ok('Expense allocation added.','expense_allocation',$this->row('expense_allocations',(int)$db->insertID(),$c),201);});}
    public function action(int$id,string$action){return$this->safe(function()use($id,$action){if(!$u=$this->user())return$this->missing();$c=$this->company($u);if(!$bill=$this->row('expense_bills',$id,$c))return$this->missing('Expense bill not found.');$old=$this->statusCode('expense_bills_status_masters','status_code',(int)$bill['status_id']);$map=['submit'=>['DRAFT','SUBMITTED','SUBMITTED'],'approve'=>['SUBMITTED','APPROVED','APPROVED'],'reject'=>['SUBMITTED','REJECTED','REJECTED'],'post'=>['APPROVED','POSTED','APPROVED'],'cancel'=>['DRAFT','CANCELLED','CANCELLED']];if(!isset($map[$action])||$old!==$map[$action][0])return$this->conflict('Invalid expense bill workflow transition.');if($action==='submit'&&db_connect()->table('expense_bill_items')->where(['bill_id'=>$id,'company_id'=>$c])->where('deleted_at',null)->countAllResults()===0)return$this->conflict('Add at least one bill item before submission.');[$from,$to,$approval]=$map[$action];$d=$this->input();$row=['status_id'=>$this->masterId('expense_bills_status_masters','status_code',$to),'updated_by'=>(int)$u->id];if($action==='submit'){$row['submitted_by']=(int)$u->id;$row['submitted_at']=$this->now();}if($action==='approve'){$row['approved_by']=(int)$u->id;$row['approved_at']=$this->now();}if($action==='post'){$row['posted_by']=(int)$u->id;$row['posted_at']=$this->now();$this->postBudgetActuals($id,$c);}$db=db_connect();$db->table('expense_bills')->where('id',$id)->update($row);$this->logStatus('BILL',$id,$from,$to,$c,(int)$u->id,$d['remarks']??null);$this->approval('BILL',$id,$approval,$c,(int)$u->id,$d['remarks']??null);$updated=$this->row('expense_bills',$id,$c);$this->notifier->notify('BILL',$updated,strtoupper($action==='submit'?'SUBMITTED':$action),(int)$u->id);return$this->ok('Expense bill '.$action.' completed.','expense_bill',$updated);});}
    private function recalculate(int$id):void{$db=db_connect();$sum=$db->table('expense_bill_items')->selectSum('taxable_amount','subtotal')->selectSum('tax_amount','tax')->where('bill_id',$id)->where('deleted_at',null)->get()->getRowArray();$b=$db->table('expense_bills')->where('id',$id)->get()->getRowArray();$subtotal=(float)($sum['subtotal']??0);$lineTax=(float)($sum['tax']??0);$taxable=max(0,$subtotal-(float)$b['discount_amount']);$gross=$taxable+$lineTax+(float)$b['cgst_amount']+(float)$b['sgst_amount']+(float)$b['igst_amount']+(float)$b['other_charges']+(float)$b['round_off'];$net=$gross-(float)$b['tds_amount'];$out=max(0,$net-(float)$b['paid_amount']);$db->table('expense_bills')->where('id',$id)->update(['subtotal'=>$subtotal,'taxable_amount'=>$taxable,'gross_amount'=>$gross,'net_payable'=>$net,'outstanding_amount'=>$out]);}
    private function postBudgetActuals(int$id,int$c):void{$db=db_connect();$rows=$db->table('expense_allocations')->select('budget_line_id,SUM(allocated_amount) amount')->where(['bill_id'=>$id,'company_id'=>$c])->where('deleted_at',null)->groupBy('budget_line_id')->get()->getResultArray();foreach($rows as$r)$db->table('project_budget_lines')->where(['id'=>$r['budget_line_id'],'company_id'=>$c])->set('actual_amount','actual_amount+'.(float)$r['amount'],false)->update();}
